package com.abhiai.abhiai_backend.controller;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.abhiai.abhiai_backend.dto.recommendation.SignalRequest;import com.abhiai.abhiai_backend.security.JwtPrincipal;import com.abhiai.abhiai_backend.service.RecommendationSignalService;import jakarta.validation.Valid;@RestController@RequestMapping("/api/v1/recommendations")public class RecommendationController{private final RecommendationSignalService s;public RecommendationController(RecommendationSignalService s){this.s=s;}@PostMapping("/signals")@ResponseStatus(HttpStatus.ACCEPTED)public void signal(@AuthenticationPrincipal JwtPrincipal p,@Valid@RequestBody SignalRequest r){s.record(p.userId(),r);}}
